import Foundation
import XCTest
@testable import WearableCore

struct WireFixture: Decodable {
    let identityHex: String
    let recordBlockHex: String
    let statusHex: String
    let commandHex: String
    let crc32: UInt32
    let dataFragmentsHex: [String]

    static func load() throws -> Self {
        // Copied from Software/testsAndDemo/tests/history-protocol-fixture.json, generated by
        // the actual firmware C++ wire structs in history_fixture.cpp.
        let url = Bundle.module.url(forResource: "history-protocol-fixture", withExtension: "json", subdirectory: "Fixtures")!
        return try JSONDecoder().decode(Self.self, from: Data(contentsOf: url))
    }
}

extension Data {
    init(hex: String) {
        self.init()
        var start = hex.startIndex
        while start < hex.endIndex {
            let end = hex.index(start, offsetBy: 2)
            append(UInt8(hex[start..<end], radix: 16)!)
            start = end
        }
    }
}

final class ProtocolTests: XCTestCase {
    func testFirmwareIdentityCommandAndCRC() throws {
        let fixture = try WireFixture.load()
        let identity = try HistoryIdentity.decode(Data(hex: fixture.identityHex))
        XCTAssertEqual(identity.deviceId, "020000123456")
        XCTAssertEqual(identity.bootId, "0102030405060708")
        XCTAssertTrue(identity.hasHistory)
        XCTAssertEqual(try HistoryCommand.ack.encode(token: 0xbeef, cursor: 105), Data(hex: fixture.commandHex))
        XCTAssertEqual(HistoryCRC.crc32(Data(hex: fixture.recordBlockHex)), fixture.crc32)
        XCTAssertEqual(HistoryCRC.crc32(Data("123456789".utf8)), 0xcbf43926)
        XCTAssertThrowsError(try HistoryCommand.open.encode(token: 0, cursor: 0))
    }

    func testFirmwareRecordsKeepExactAcquisitionTimestampsAndSignedIMU() throws {
        let fixture = try WireFixture.load()
        let records = try HistoryRecord.decodeBlock(Data(hex: fixture.recordBlockHex), first: 100)
        XCTAssertEqual(records.count, 5)
        XCTAssertEqual(records[0].timeUs, 9_007_199_254_740_993)
        XCTAssertEqual(records[4].timeUs, 9_007_199_254_900_993)
        let imu = records[1]
        var live = Data([1, imu.flags, 0, 0, 0, 0, 0, 0]); live.append(imu.raw.subdata(in: 16..<28))
        guard case .imu(let reading) = try TelemetryPacket.decode(live, kind: .imu) else { return XCTFail("Wrong kind") }
        XCTAssertEqual(reading.accelerationG, [-1, 0.5, 8])
        XCTAssertEqual(reading.angularVelocityDps, [-2000, 2000, 123.4])
    }

    func testDefaultMTUFragmentsOutOfOrderAndDuplicate() throws {
        let fixture = try WireFixture.load()
        let assembler = try HistoryBlockAssembler(status: HistoryStatus.decode(Data(hex: fixture.statusHex)))
        let fragments = fixture.dataFragmentsHex.map { Data(hex: $0) }.reversed()
        for fragment in fragments {
            _ = try assembler.accept(fragment)
            XCTAssertEqual(try assembler.accept(fragment).added, 0)
        }
        XCTAssertEqual(assembler.bytes, Data(hex: fixture.recordBlockHex))
        XCTAssertTrue(try assembler.accept(Data(hex: fixture.dataFragmentsHex[0])).complete)
    }

    func testFragmentConflictsWrongTokenBoundsAndChecksum() throws {
        let fixture = try WireFixture.load(), status = try HistoryStatus.decode(Data(hex: fixture.statusHex))
        let assembler = try HistoryBlockAssembler(status: status)
        var fragment = Data(hex: fixture.dataFragmentsHex[0])
        var otherToken = fragment; otherToken[0] ^= 1
        XCTAssertEqual(try assembler.accept(otherToken).added, 0)
        XCTAssertThrowsError(try assembler.accept(Data([0])))
        _ = try assembler.accept(fragment); fragment[8] ^= 1
        XCTAssertThrowsError(try assembler.accept(fragment))
        var tooFar = Data(hex: fixture.dataFragmentsHex[0]); tooFar[2] = 255
        XCTAssertThrowsError(try assembler.accept(tooFar))
        let corrupt = try HistoryBlockAssembler(status: HistoryStatus(type: .block, token: status.token,
            first: status.first, end: status.end, detail: status.detail ^ 1, count: status.count))
        for hex in fixture.dataFragmentsHex.dropLast() { _ = try corrupt.accept(Data(hex: hex)) }
        XCTAssertThrowsError(try corrupt.accept(Data(hex: fixture.dataFragmentsHex.last!)))
    }

    func testRejectsMalformedPacketsAndExhaustedRecordIDs() throws {
        let fixture = try WireFixture.load()
        var identity = Data(hex: fixture.identityHex); identity[18] = 1
        XCTAssertThrowsError(try HistoryIdentity.decode(identity))
        var records = Data(hex: fixture.recordBlockHex); records[32] = 7
        XCTAssertThrowsError(try HistoryRecord.decodeBlock(records, first: 100))
        XCTAssertThrowsError(try HistoryRecord.decodeBlock(Data(count: 32), first: .max))
        XCTAssertThrowsError(try HistoryBlockAssembler(status: HistoryStatus(type: .block, token: 1, first: .max, end: .max, count: 1)))
        XCTAssertThrowsError(try TelemetryPacket.decode(Data(count: 19), kind: .ppg))
        var packet = Data(count: 20); packet[0] = 2
        XCTAssertThrowsError(try TelemetryPacket.decode(packet, kind: .depth))
    }

    func testInvalidReadingsRemainUnknownAndSystemMotorBitIsPreserved() throws {
        var packet = Data(count: 20); packet[0] = 1
        guard case .depth(let depth) = try TelemetryPacket.decode(packet, kind: .depth) else { return XCTFail() }
        XCTAssertNil(depth.depthM); XCTAssertNil(depth.pressurePa); XCTAssertNil(depth.temperatureC)
        packet[1] = 7; packet[16] = 255; packet[17] = 255; packet[18] = 255; packet[19] = 255
        guard case .ppg(let ppg) = try TelemetryPacket.decode(packet, kind: .ppg) else { return XCTFail() }
        XCTAssertNil(ppg.heartRateBpm); XCTAssertNil(ppg.spo2Percent)
        packet[1] = 0xe0
        guard case .system(let system) = try TelemetryPacket.decode(packet, kind: .system) else { return XCTFail() }
        XCTAssertTrue(system.vibrationMotor); XCTAssertTrue(system.vibrationOn); XCTAssertTrue(system.countdownActive)
        XCTAssertNil(system.batteryV)
    }
}
